window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-40bdb9e6fdfccb0b"]={"versions": [{"id": "FIG-40bdb9e6fdfccb0b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptuelles Metamodell- und Architekturdiagramm zur Veranschaulichung der Modellbeziehungen und Tracing-Regeln für Datentypen zwischen der AUTOSAR Abstract Platform (AP) und konkreten Plattformen (Classic Platform / Adaptive Platform). Es stellt einen zulässigen Transformations- bzw. Tracing-Pfad (links) einem unzulässigen direkten Tracing (rechts) gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Abstract Platform - (XP) ApplicationDataType</strong>: Plattformunabhängige Datentypdefinition auf Ebene der Abstract Platform.\n</li><li><strong>Classic/Adaptive Platform - (XP) ApplicationDataType</strong> (rot umrandet/hervorgehoben): Plattformspezifisches Anwendungsdatenelement, das über eine <code>&lt;&lt;tracing&gt;&gt;</code>-Beziehung (gestrichelte Doppelpfeillinie) mit dem <code>(XP) ApplicationDataType</code> der Abstract Platform verknüpft ist.\n</li><li><strong>Classic/Adaptive Platform - AbstractImplementationDataType</strong>: Konkreter Implementierungsdatentyp auf Plattformebene, der über eine <code>DataTypeMap</code> (durchgezogene Doppelpfeillinie) an den plattformspezifischen <code>(XP) ApplicationDataType</code> gekoppelt ist.\n</li><li><strong>Direktes Tracing (rechts)</strong>: Gestrichelte rote Doppelpfeillinie mit Blitzsymbol zwischen <code>Abstract Platform - (XP) ApplicationDataType</code> und <code>Classic/Adaptive Platform - AbstractImplementationDataType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Regeldiagramm ohne zeitlichen Ablauf:</p>\n<ul class=\"fig-list\"><li>Links: Das Tracing erfolgt konform über ein zwischengeschaltetes <code>(XP) ApplicationDataType</code> auf Plattformebene, welches per <code>DataTypeMap</code> auf den <code>AbstractImplementationDataType</code> abgebildet wird.\n</li><li>Rechts: Ein direktes Tracing zwischen dem abstrakten <code>(XP) ApplicationDataType</code> und dem plattformspezifischen <code>AbstractImplementationDataType</code> wird durch die rot markierte, gebrochene/durchblitzte Verbindungslinie als unzulässig (prohibited) gekennzeichnet.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel: Ein direktes Tracing von abstrakten Anwendungsdatentypen (<code>ApplicationDataType</code>) der Abstract Platform auf Implementierungsdatentypen (<code>AbstractImplementationDataType</code>) konkreter Plattformen ist unzulässig. Modellierer und Generatoren müssen den Weg über plattformspezifische Anwendungsdatentypen und eine entsprechende <code>DataTypeMap</code> wählen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-36f4448c3776d98a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptuelles Metamodell- und Architekturdiagramm zur Veranschaulichung der Modellbeziehungen und Tracing-Regeln für Datentypen zwischen der AUTOSAR Abstract Platform (AP) und konkreten Plattformen (Classic Platform / Adaptive Platform). Es stellt einen zulässigen Transformations- bzw. Tracing-Pfad (links) einem unzulässigen direkten Tracing (rechts) gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Abstract Platform - ApplicationDataType</strong>: Plattformunabhängige Datentypdefinition auf Ebene der Abstract Platform.\n</li><li><strong>Classic/Adaptive Platform - ApplicationDataType</strong> (rot umrandet/hervorgehoben): Plattformspezifisches Anwendungsdatenelement, das über eine <code>&lt;&lt;tracing&gt;&gt;</code>-Beziehung (gestrichelte Doppelpfeillinie) mit dem <code>ApplicationDataType</code> der Abstract Platform verknüpft ist.\n</li><li><strong>Classic/Adaptive Platform - AbstractImplementationDataType</strong>: Konkreter Implementierungsdatentyp auf Plattformebene, der über eine <code>DataTypeMap</code> (durchgezogene Doppelpfeillinie) an das plattformspezifische <code>ApplicationDataType</code> gekoppelt ist.\n</li><li><strong>Direktes Tracing (rechts)</strong>: Gestrichelte rote Doppelpfeillinie mit Blitzsymbol zwischen <code>Abstract Platform - ApplicationDataType</code> und <code>Classic/Adaptive Platform - AbstractImplementationDataType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Regeldiagramm ohne zeitlichen Ablauf:</p>\n<ul class=\"fig-list\"><li>Links: Das Tracing erfolgt konform über ein zwischengeschaltetes <code>ApplicationDataType</code> auf Plattformebene, welches per <code>DataTypeMap</code> auf den <code>AbstractImplementationDataType</code> abgebildet wird.\n</li><li>Rechts: Ein direktes Tracing zwischen dem abstrakten <code>ApplicationDataType</code> und dem plattformspezifischen <code>AbstractImplementationDataType</code> wird durch die rot markierte, gebrochene/durchblitzte Verbindungslinie als unzulässig (prohibited) gekennzeichnet.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel: Ein direktes Tracing von abstrakten Anwendungsdatentypen (<code>ApplicationDataType</code>) der Abstract Platform auf Implementierungsdatentypen (<code>AbstractImplementationDataType</code>) konkreter Plattformen ist unzulässig. Modellierer und Generatoren müssen den Weg über plattformspezifische Anwendungsdatentypen und eine entsprechende <code>DataTypeMap</code> wählen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-40bdb9e6fdfccb0b", "to": "FIG-36f4448c3776d98a", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung in den Blöcken <code>Abstract Platform</code> (links und rechts) sowie <code>Classic/Adaptive Platform</code> (links Mitte): Präfix <code>(XP)</code> vor <code>ApplicationDataType</code> entfernt (neu jeweils <code>ApplicationDataType</code>).\n</li></ul>"}]};
